package com.jobsphere.controller;

import com.jobsphere.entity.PasswordResetToken; import com.jobsphere.entity.User;
import com.jobsphere.repository.PasswordResetTokenRepository; import com.jobsphere.repository.UserRepository;
import com.jobsphere.service.AuthService; import com.jobsphere.service.EmailService; import com.jobsphere.service.TokenService;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.web.bind.annotation.*;
import java.time.LocalDateTime; import java.util.*;

@RestController @RequestMapping("/api/auth")
public class AuthController {
 private final UserRepository repo; private final TokenService tokens; private final AuthService auth; private final EmailService email; private final PasswordResetTokenRepository resets; private final BCryptPasswordEncoder enc=new BCryptPasswordEncoder();
 public AuthController(UserRepository r,TokenService t,AuthService a,EmailService e,PasswordResetTokenRepository p){repo=r;tokens=t;auth=a;email=e;resets=p;}
 record Register(String fullName,String email,String phone,String password,String confirmPassword){} record Login(String email,String password){} record Forgot(String email){} record Verify(String email,String otp){} record Reset(String email,String otp,String newPassword,String confirmPassword){}
 @PostMapping("/register") public Map<String,Object> register(@RequestBody Register x){String name=trim(x.fullName()),em=trim(x.email()),phone=trim(x.phone()); if(!name.matches("[A-Za-z][A-Za-z .'-]{1,119}"))throw new RuntimeException("Full name must contain 2–120 valid characters."); if(!em.matches("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$"))throw new RuntimeException("Please enter a valid email address."); if(!phone.isBlank()&&!phone.matches("07\\d{8}"))throw new RuntimeException("Phone number must contain exactly 10 digits and start with 07."); if(!strong(x.password()))throw new RuntimeException("Password must be 8–64 characters with uppercase, lowercase, number and special character."); if(!Objects.equals(x.password(),x.confirmPassword()))throw new RuntimeException("Confirm password does not match the password."); if(repo.findByEmailIgnoreCase(em).isPresent())throw new RuntimeException("An account with this email already exists. Please sign in."); User u=auth.create(name,em,x.password());
 boolean emailSent=true;
 try { email.sendRegistrationSuccess(u.email,u.fullName); }
 catch(Exception ignored) { emailSent=false; }
 String message=emailSent
         ? "Registration successful. A confirmation email has been sent to "+u.email+"."
         : "Registration successful, but the confirmation email could not be sent. Please check the email configuration.";
 return Map.of("success",true,"message",message,"emailSent",emailSent,"userId",u.id);}
 @PostMapping("/login") public Map<String,Object> login(@RequestBody Login x){String em=trim(x.email());if(em.isBlank())throw new RuntimeException("Please enter your email address.");if(x.password()==null||x.password().isBlank())throw new RuntimeException("Please enter your password.");User u=repo.findByEmailIgnoreCase(em).orElseThrow(()->new RuntimeException("No account was found with this email address."));if(!Boolean.TRUE.equals(u.active))throw new RuntimeException("This account has been disabled. Please contact JOBSPHERE support.");if(!auth.matches(x.password(),u.passwordHash))throw new RuntimeException("The password is incorrect. Please try again.");String tk=tokens.issue(u.id); try{email.sendLoginAlert(u.email,u.fullName);}catch(Exception ignored){} return Map.of("success",true,"token",tk,"user",Map.of("id",u.id,"fullName",u.fullName,"email",u.email,"role",u.role.name()));}
 @PostMapping("/forgot-password") public Map<String,Object> forgot(@RequestBody Forgot x){String em=trim(x.email()).toLowerCase(Locale.ROOT); User u=repo.findByEmailIgnoreCase(em).orElseThrow(()->new RuntimeException("No account was found with this email address.")); String otp=String.format("%06d",new Random().nextInt(1000000)); PasswordResetToken p=new PasswordResetToken();p.userId=u.id;p.codeHash=enc.encode(otp);p.expiresAt=LocalDateTime.now().plusMinutes(10);p.createdAt=LocalDateTime.now();p.used=false;p.attempts=0;resets.save(p); try{email.sendPasswordOtp(u.email,u.fullName,otp);}catch(Exception e){throw new RuntimeException("We could not send the OTP email. Check the email configuration and try again.");} return Map.of("success",true,"message","A 6-digit OTP has been sent to your email address.");}
 @PostMapping("/verify-otp") public Map<String,Object> verify(@RequestBody Verify x){PasswordResetToken p=valid(x.email(),x.otp());return Map.of("success",true,"message","OTP verified. You can now create a new password.");}
 @PostMapping("/reset-password") public Map<String,Object> reset(@RequestBody Reset x){if(!strong(x.newPassword()))throw new RuntimeException("New password must be 8–64 characters with uppercase, lowercase, number and special character.");if(!Objects.equals(x.newPassword(),x.confirmPassword()))throw new RuntimeException("Confirm password does not match the new password.");PasswordResetToken p=valid(x.email(),x.otp());User u=repo.findByEmailIgnoreCase(x.email().trim()).orElseThrow();u.passwordHash=enc.encode(x.newPassword());repo.save(u);p.used=true;resets.save(p);return Map.of("success",true,"message","Password changed successfully. You can now sign in.");}
 private PasswordResetToken valid(String email,String otp){User u=repo.findByEmailIgnoreCase(trim(email)).orElseThrow(()->new RuntimeException("No account was found with this email address."));PasswordResetToken p=resets.findTopByUserIdAndUsedFalseOrderByCreatedAtDesc(u.id).orElseThrow(()->new RuntimeException("No active OTP was found. Request a new OTP."));if(p.expiresAt.isBefore(LocalDateTime.now()))throw new RuntimeException("This OTP has expired. Request a new one.");if(p.attempts>=5)throw new RuntimeException("Too many OTP attempts. Request a new OTP.");p.attempts++;resets.save(p);if(!enc.matches(trim(otp),p.codeHash))throw new RuntimeException("The OTP is incorrect.");return p;}
 @PostMapping("/logout") public Map<String,Object> logout(@RequestHeader(value="Authorization",required=false) String h){if(h!=null)tokens.revoke(h.replaceFirst("^Bearer\\s*",""));return Map.of("success",true);}
 private static String trim(String s){return s==null?"":s.trim();} private static boolean strong(String s){return s!=null&&s.matches("^(?=.*[A-Z])(?=.*[a-z])(?=.*\\d)(?=.*[^A-Za-z\\d]).{8,64}$");}
}
